#!/usr/bin/env python3
"""Verify LS5 checkpoints/result and render a concise audit report."""
import hashlib,json
from pathlib import Path
from collections import Counter
from ls5_screen import validate_checkpoint,seal
from seti_repeater.light_sail import apply_abacad_veto

def main():
    config_path=Path('config/ls5_kepler160_s_light_sail.json');config=json.loads(config_path.read_text());digest=hashlib.sha256(config_path.read_bytes()).hexdigest()
    result=json.loads(Path('results_ls5_screen/screen.json').read_text())
    if result['result_sha256']!=seal({k:v for k,v in result.items() if k!='result_sha256'}):raise RuntimeError('result identity mismatch')
    if result['config_sha256']!=digest:raise RuntimeError('result/config mismatch')
    scans=[validate_checkpoint(json.loads(Path('results_ls5_screen',s['label']+'.json').read_text()),s,digest) for s in config['selected_sequence']]
    if scans!=result['scans']:raise RuntimeError('checkpoint/result mismatch')
    d=config['medium_resolution_screen'];candidates=apply_abacad_veto(scans,on_threshold=d['on_score_threshold'],off_threshold=d['off_veto_score_threshold'],minimum_frequency_overlap=d['off_veto_frequency_overlap'])
    if candidates!=result['candidates']:raise RuntimeError('veto does not reproduce')
    survivors=[c for c in candidates if c['survives_adjacent_off_veto']]
    if len(survivors)!=result['surviving_event_count'] or len(candidates)!=result['on_threshold_event_count']:raise RuntimeError('count mismatch')
    total=sum(s['source_size_bytes'] for s in scans);ontime=sum(s['expected_filterbank_header']['ntime']*s['expected_filterbank_header']['tsamp_s'] for s in config['selected_sequence'] if s['role']=='ON')
    inv=json.loads(Path('results_ls5_inventory/expanded_matches.json').read_text())
    pre=json.loads(Path('results_ls5_header/qualified.json').read_text())
    lines=['# LS5 Kepler-160 S-band archival screen','',f"Status: **{result['status']}**.",'',f"The fifth distinct LS target has now received a medium-resolution spectral screen. Six public GBT scans from 14 June 2020 were processed in the frozen 1.8–2.8 GHz band, using unchanged LS1 broadband templates and the LS4B SIGPROC adapter. Total input: {total:,} bytes; designated ON integration: {ontime:.3f} seconds.",'','| Scan | Archival role | Retained score ≥6 events | Score ≥8 events | Retention truncated |','|---|---|---:|---:|---|']
    for s in scans:
        count=sum(e['score']>=8 for e in s['search']['events'])
        lines.append(f"| {s['label']} | {s['role']} | {len(s['search']['events'])} | {count} | {s['search']['retention_truncated']} |")
    lines+=['',f"**{len(candidates)} ON threshold events; {len(survivors)} survive the adjacent-OFF veto.** These counts describe detector windows, not independent physical signals.",'']
    if survivors:lines+=['Survivors require a separately frozen HTR follow-up and pointing verification. No technosignature is claimed. No HTR samples have been opened.']
    else:lines+=['No event qualifies for HTR follow-up under the frozen rule. This closes this sequence and detector only. No technosignature is claimed.']
    audit=json.loads(Path('results_ls5_screen/later_off_audit.json').read_text())
    if audit['source_result_identity']!=result['result_sha256']:raise RuntimeError('audit source mismatch')
    lines+=['','## Three retained windows and post-hoc control check','', 'All three primary survivors occur late in A1 and use the 64-second template. A labelled post-hoc audit of already screened C1/D1 data finds frequency-overlapping events above score 6 for every survivor. C1 and D1 are not A1’s frozen adjacent control. This flags interference concerns without changing the primary three-survivor result; it does not prove simultaneous emission or common physical origin. No additional spectra were read.','', '| A1 frequency interval (MHz) | A1 time (s) | A1 score | C1 max overlapping score | D1 max overlapping score |','|---|---:|---:|---:|---:|']
    for row in audit['rows']:
        e=row['event'];off={o['label']:o for o in row['off_checks']}
        lines.append(f"| {e['frequency_start_mhz']:.3f}–{e['frequency_stop_mhz']:.3f} | {e['time_start_s']:.1f}–{e['time_stop_s']:.1f} | {e['score']:.2f} | {off['C1']['maximum_score']:.2f} | {off['D1']['maximum_score']:.2f} |")
    lines+=['', 'Any follow-up should first address late-scan baseline structure and these nonadjacent control counterparts. None is presently a credible stellar technosignature candidate.']
    lines+=['','## Qualification and limits','','All six SIGPROC headers call the source KEPLER-160. Roles follow the dedicated catalogue and the independently published alternating scan sequence. The original name-based rejection is preserved in results_ls5_header/preflight.json; the explicit, prespectral role amendment is LS5_POINTING_AMENDMENT.md.','', 'The last designated ON header is 0.248 degrees from the published target coordinates; its centering is unresolved. The approximate b/c separation is 31.912 stellar radii, not a close conjunction. The 31.786–32.033 period/epoch corner range omits known transit-timing variations, stellar-radius uncertainty and unknown orbital nodes. It is not a confidence interval. No calibrated target sensitivity or occurrence limit is inferred.','', 'The 4–64 second envelope search is a reanalysis. [Perez et al. (2020)](https://seti.berkeley.edu/kepler160/BL_Kepler160.pdf) already searched these observations for narrowband drift signals and short artificially dispersed broadband pulses. [Heller et al. (2020)](https://arxiv.org/abs/2006.02123) supplies the NASA-default b/c ephemerides and describes transit-timing variations. Their results and sensitivities are not transferred to this detector.','','## Selection record','', 'The initial five-host shortlist had no exact host-alias match. The declared expansion queried '+str(inv['queried_planet_count'])+' default transiting planet rows, including '+str(inv['multi_transit_host_count'])+' hosts with at least two transiting rows. After excluding the four previously searched LS hosts, four systems matched the limited host/HD/HIP/TIC identifier cross-match. This is not a complete all-alias survey.','', '| Matched new host | Dedicated cadences | Outcome |','|---|---:|---|','| GJ 9827 | 0 | One medium product in target-only query; no dedicated sequence |','| LHS 1903 | 0 | Three medium products on separate dates; no dedicated sequence |','| HIP 41378 | 0 | Four medium products; default rows lack complete geometry |','| Kepler-160 | 3 | L and S have six scans; dedicated C listing has five |','', 'Kepler-160 target-only metadata also exposes observations from September 2020. These were not substituted into this frozen June sequence and remain a possible later epoch.','','## Reproducibility','','Public freeze commit: `54c35156f83ee1fdaf8508f6e71fa07ae78598dc`, tree `30edc156a59058b94e2c340b37a1393643d6b9b4`, published and ref-verified before spectral contact.','',f"Configuration SHA-256: `{digest}`. Result identity: `{result['result_sha256']}`.",'','All 138 LS tests passed, including four checkpoint integrity tests. The broad repository suite was also attempted: its first attempts exposed missing dependencies; after installation, its log ended in an older M36 inventory test without a unittest completion summary. No full-suite pass is claimed. The completed LS test suite covers the unchanged detector, filterbank adapter and new checkpoint handling.','', 'The report generator verifies result identity, every checkpoint against the frozen configuration, and exact reproduction of the adjacent-OFF veto. DATA_MANIFEST_LS5.sha256 records each full-file digest and public URL. Raw files are excluded from commits.','', '```bash','PYTHONPATH=src:scripts python -m unittest discover -s tests -p \'test_ls*.py\' -v','PYTHONPATH=src:scripts python scripts/ls5_screen.py config/ls5_kepler160_s_light_sail.json','PYTHONPATH=src:scripts python scripts/ls5_result_report.py','```','']
    Path('LS5_KEPLER160_RESULT.md').write_text('\n'.join(lines))
    print(json.dumps({'status':result['status'],'on_events':len(candidates),'survivors':len(survivors),'raw_input_bytes':total,'designated_on_seconds':ontime,'result_identity':result['result_sha256']},indent=2))
if __name__=='__main__':main()
